package com.primehr.security;import com.primehr.integration.administrative.*;import org.springframework.security.access.AccessDeniedException;import org.springframework.stereotype.Component;
@Component public class PerformanceCommitmentPermissionGuard{public static final String OFFICE="primehr.office-performance-commitment",INDIVIDUAL="primehr.individual-performance-commitment";private final AdministrativeAuthorizationClient client;public PerformanceCommitmentPermissionGuard(AdministrativeAuthorizationClient c){client=c;}public PermissionDataScope require(String form,PrimeHrAction action,String token){String feature="IPCR".equals(form)?INDIVIDUAL:OFFICE;EffectiveFeaturePermission p=client.resolve(feature,token);boolean ok=p.administrator()||p.canAccess()&&switch(action){case ACCESS->true;case ADD->p.canAdd();case EDIT->p.canEdit();case SUBMIT->p.canSubmit();case APPROVE->p.canApprove();case FINALIZE->p.canFinalize();default->false;};if(!ok)throw new AccessDeniedException("Performance commitment permission is required");PermissionDataScope scope=p.administrator()?PermissionDataScope.AGENCY_WIDE:p.dataScope();if(feature.equals(INDIVIDUAL)&&scope!=PermissionDataScope.OWN_RECORDS&&scope!=PermissionDataScope.ASSIGNED_RECORDS&&scope!=PermissionDataScope.AGENCY_WIDE)throw new AccessDeniedException("Individual commitment scope is not permitted");if(feature.equals(OFFICE)&&scope!=PermissionDataScope.ASSIGNED_RECORDS&&scope!=PermissionDataScope.AGENCY_WIDE)throw new AccessDeniedException("Office commitment scope is not permitted");return scope;}}
